const SOVEREIGNTY_META = {"mammouth":{"display_name":"Mammouth AI","jurisdiction":{"country":"France","code":"FR","inEu":true,"detail":"French company (Paris); operates under GDPR.","source":"https://info.mammouth.ai/docs/privacy-policy/"},"retention":{"detail":"Prompts are kept for conversation history; monitoring logs are deleted after at most 30 rolling days. Upstream model providers do not retain Mammouth prompts beyond 30 days.","source":"https://info.mammouth.ai/docs/about-privacy/"},"training":{"detail":"No training of models with prompts sent through Mammouth.","source":"https://info.mammouth.ai/docs/about-privacy/"},"hosting":{"detail":"Gateway/control plane hosted in EU (Hetzner Germany, Neon Germany, GCP Belgium, Cloudflare EU).","source":"https://info.mammouth.ai/docs/terms-of-service/"},"region":{"detail":"Inference is global: Annex lists Fireworks AI (USA), xAI (USA), and OpenAI/Anthropic/Google as EU/USA. DPA §7.1 says 'primarily' in EEA – some models require US processing via SCCs.","source":"https://info.mammouth.ai/docs/terms-of-service/"},"routing":{"detail":"Aggregates multiple upstream providers (OpenAI, Anthropic, Mistral, Google, Fireworks, xAI, etc.); some require US processing. No OpenRouter is listed as sub-processor.","source":"https://info.mammouth.ai/docs/terms-of-service/"}},"cortecs":{"display_name":"Cortecs","jurisdiction":{"country":"Austria","code":"AT","inEu":true,"detail":"Imprint: Commercial Court of Vienna, company register number 560802i.","source":"https://cortecs.ai/imprint"},"retention":{"detail":"PAYLOAD DATA (prompts/completions) is not retained – recovery is technically impossible and payload is excluded from backups. OPERATIONAL METADATA (timestamps, model selection, token counts, error codes, pseudonymous user IDs) retained up to 12 months for stability/debugging. Data sent to an inference sub-processor is subject to that provider's own retention policy.","source":"https://cortecs.ai/dpa"},"training":{"detail":"Cortecs states 'No Training': private customer data should never be used to train AI models; Cortecs acts as primary data processor.","source":"https://cortecs.ai/"},"hosting":{"detail":"Gateway/control plane hosted in EU (OVH SA France, BunnyWay Slovenia, plus EU auth). Account data retained per Austrian §132 (7 years).","source":"https://cortecs.ai/privacyPolicy"},"region":{"detail":"Inference hosted within the EU – all models run on EU-native clouds.","source":"https://cortecs.ai/"},"routing":{"detail":"Routes workloads to models hosted within the EU; GDPR-native positioning with EU hosting partners.","source":"https://cortecs.ai/"}},"mistral":{"display_name":"Mistral AI","jurisdiction":{"country":"France","code":"FR","inEu":true,"detail":"French company operating under EU data protection law.","source":"https://legal.mistral.ai/terms/privacy-policy"},"retention":{"detail":"API inputs and outputs are kept for the period needed to generate the output plus up to thirty (30) rolling days for abuse monitoring, unless Zero Data Retention is activated (available for eligible stateless pay-as-you-go API calls).","source":"https://legal.mistral.ai/terms/privacy-policy"},"training":{"detail":"Data sent through the API is not used for model training.","source":"https://docs.mistral.ai/admin/monitor-comply/privacy-data-controls"},"hosting":{"detail":"Control plane hosted in EU (La Plateforme).","source":"https://mistral.ai/"},"region":{"detail":"Global endpoint api.mistral.ai makes no region commitment; inference may run outside the EU (sub-processors include Google Cloud and Azure in EU and US). Only api.eu.mistral.ai (Mistral AI Regional, 1.1×) pins inference to the EU.","source":"https://docs.mistral.ai/inference/regional-inference"},"routing":{"detail":"First-party inference platform; global endpoint may route to hyperscaler subprocessors (Google Cloud, Azure).","source":"https://trust.mistral.ai/subprocessors"}},"mistral-regional":{"display_name":"Mistral AI Regional","jurisdiction":{"country":"France","code":"FR","inEu":true,"detail":"French company operating under EU data protection law — same jurisdiction as Mistral AI; regional product is a routing option, not a separate legal entity.","source":"https://legal.mistral.ai/terms/privacy-policy"},"retention":{"detail":"Same 30-day abuse-monitoring retention as Mistral AI; Zero Data Retention available for eligible stateless calls (also on the regional endpoint).","source":"https://legal.mistral.ai/terms/privacy-policy"},"training":{"detail":"Data sent through the API is not used for model training.","source":"https://docs.mistral.ai/admin/monitor-comply/privacy-data-controls"},"hosting":{"detail":"Control plane hosted in EU (La Plateforme); regional endpoint is api.eu.mistral.ai.","source":"https://docs.mistral.ai/inference/regional-inference"},"region":{"detail":"Inference pinned to EU via api.eu.mistral.ai (1.1× surcharge); guarantees EU data residency. Unlike the default La Plateforme endpoint (EU by default, optional pin), this offer is EU-only.","source":"https://docs.mistral.ai/inference/regional-inference"},"routing":{"detail":"First-party inference — same Mistral fleet, but routed exclusively to the EU fleet via the regional endpoint.","source":"https://docs.mistral.ai/inference/regional-inference"}},"edenai":{"display_name":"Eden AI","jurisdiction":{"country":"France","code":"FR","inEu":true,"detail":"Eden AI is a French company operating under EU data protection law including GDPR.","source":"https://www.edenai.co/privacy"},"retention":{"detail":"Zero Data Retention is implemented at the gateway level with configurable log retention; the dedicated EU endpoint advertises zero data retention. Upstream provider retention varies and is documented per provider.","source":"https://www.edenai.co/post/zero-data-retention-for-ai-apis-what-it-is-why-enterprises-need-it-and-how-to-get-it"},"training":{"detail":"'We do not use your data to train models' (Eden AI privacy policy).","source":"https://www.edenai.co/privacy"},"hosting":{"detail":"Gateway hosted in secure European data centers.","source":"https://www.edenai.co/docs/v3/data-governance/servers-location"},"region":{"detail":"Inference is global by default (api.edenai.run). Only api.eu.edenai.run guarantees EU-only inference via EU-eligible providers.","source":"https://www.edenai.co/docs/v3/data-governance/eu-endpoint"},"routing":{"detail":"Routes to 50+ underlying providers; per-provider training/retention/ZDR posture is published in structured docs.","source":"https://www.edenai.co/docs/v3/data-governance/provider-data-policies"}},"opper":{"display_name":"Opper AI","jurisdiction":{"country":"Sweden","code":"SE","inEu":true,"detail":"Opper Technology AB, Enebyberg, Sweden, reg. no. 559446-3720.","source":"https://opper.ai/privacy-policy"},"retention":{"detail":"Data retention is configurable, including zero retention. Model providers may retain request data according to their own policies.","source":"https://opper.ai/security-overview"},"training":{"detail":"Opper does not use customer data to train models; the sub-processor list documents that listed model providers do not train on customer requests/responses by default.","source":"https://opper.ai/security-overview"},"hosting":{"detail":"Gateway hosted in AWS Stockholm (eu-north-1).","source":"https://opper.ai/ai-compliance"},"region":{"detail":"Inference is global by routing choice: EU routes (AWS Bedrock EU, Azure EU, GCP EU, Mistral, Berget AI) stay in EU; other routes leave EU. EU residency only when EU route is selected.","source":"https://opper.ai/ai-compliance"},"routing":{"detail":"Gateway in front of listed model providers; sub-processor list records provider-side postures.","source":"https://opper.ai/ai-compliance"}},"eurouter":{"display_name":"EURouter","jurisdiction":{"country":"Netherlands","code":"NL","inEu":true,"detail":"Company headquartered in Utrecht, Netherlands.","source":"https://www.eurouter.ai/providers"},"retention":{"detail":"Zero data retention by default, with guaranteed EU data residency and GDPR compliance.","source":"https://www.eurouter.ai/privacy"},"training":{"detail":"EURouter does not use Customer API Data to train, fine-tune or improve AI models and does not sell Customer API Data; shall not use Input Data to train, fine-tune, or improve any AI Model.","source":"https://www.eurouter.ai/dpa"},"hosting":{"detail":"Gateway hosted in France on renewable energy; compute in Scaleway NL-AMS (Amsterdam) and FR-PAR.","source":"https://www.eurouter.ai/"},"region":{"detail":"Inference handled inside Europe only – EU/EEA configurations only (Scaleway, OVHcloud, Mistral AI, IONOS, Nebius etc.).","source":"https://www.eurouter.ai/"},"routing":{"detail":"Routes to EU-hosted offerings of multiple model providers.","source":"https://www.eurouter.ai/providers"}},"greenpt":{"display_name":"GreenPT","jurisdiction":{"country":"Netherlands","code":"NL","inEu":true,"detail":"GreenPT BV, Plompetorengracht 4, 3512 CC Utrecht, Netherlands, Chamber of Commerce 97084360, DPO mail@greenpt.ai (GDPR).","source":"https://docs.greenpt.ai/privacy/privacy-policy"},"retention":{"detail":"API payloads & audio input: no persistent storage — processed in-memory only and discarded immediately after transcription (API scope). Chat history retention (12 months, outside API scope) does not apply to API calls.","source":"https://docs.greenpt.ai/privacy/privacy-policy"},"training":{"detail":"We never use your conversations, documents, or API traffic to train AI models, ours or anyone else's. Every model is self-hosted on GreenPT infrastructure, so your data never leaves our environment.","source":"https://greenpt.com/privacy"},"hosting":{"detail":"All data hosted exclusively in EU data centres (France) on 100% renewable energy; primary sub-processor Scaleway SAS France (ISO 27001, 100% renewable).","source":"https://docs.greenpt.ai/privacy/privacy-policy"},"region":{"detail":"Personal data processed exclusively within EU data centres located in France; no transfer outside EEA without explicit authorization. Sub-processors: Scaleway SAS France primary; Mollie NL for payments; Brave Search USA only for search.greenpt.ai.","source":"https://docs.greenpt.ai/privacy/privacy-policy"},"routing":{"detail":"API proxy aggregates EU-hosted open-weights models (Scaleway France); on-premise deployment option for full sovereignty.","source":"https://docs.greenpt.ai/privacy/privacy-policy"}},"requesty":{"display_name":"Requesty AI","jurisdiction":{"country":"United Kingdom","code":"GB","inEu":false,"detail":"Requesty Ltd, 71-75 Shelton Street, Covent Garden, London WC2H 9JQ, established in the United Kingdom.","source":"https://www.requesty.ai/privacy"},"retention":{"detail":"Zero Data Retention is an opt-in organization-level mode with a hard guarantee that no request/response content is stored. When logging is enabled, data is stored encrypted within the EU for up to 30 days. Provider-side retention/training still depends on the routed model (exposed per model via the API).","source":"https://www.requesty.ai/privacy"},"training":{"detail":"Requesty does not train machine learning models on your data, and never sells personal information. Provider-side training still depends on the upstream provider per model.","source":"https://www.requesty.ai/privacy"},"hosting":{"detail":"Gateway hosted globally (nearest routing): EU Frankfurt (eu-central-1), US Virginia, APAC Singapore. EU data stays in Frankfurt only via router.eu.requesty.ai.","source":"https://www.requesty.ai/"},"region":{"detail":"Inference is global by routing/model choice; EU-region deployments (Bedrock eu-central-1, Azure France Central/Sweden Central, Vertex EU, Mistral EU) only when EU gateway and EU-eligible model/route are selected.","source":"https://www.requesty.ai/eu"},"routing":{"detail":"Requests travel to the upstream LLM provider; each has its own retention and training policies, tagged per model in the catalog.","source":"https://docs.requesty.ai/features/data-privacy"}},"openrouter":{"display_name":"OpenRouter","jurisdiction":{"country":"United States","code":"US","inEu":false,"detail":"US-based aggregator (New York).","source":"https://www.whatjobs.com/news/stripe-agrees-to-buy-openrouter-as-payments-giant-pushes-deeper-into-ai/"},"retention":{"detail":"Retention is defined per endpoint/provider; privacy settings can restrict routing to Zero-Retention endpoints. OpenRouter's own retention policy and caching behavior are documented separately.","source":"https://openrouter.ai/docs/guides/features/zdr"},"training":{"detail":"Some routed providers may train on prompts according to their own policies; an account setting controls whether routing to such providers is allowed. ZDR endpoints cannot train.","source":"https://openrouter.ai/docs/guides/privacy/provider-logging"},"hosting":{"detail":"Control plane global (Cloudflare + GCP).","source":"https://openrouter.ai/authorized-sub-processors"},"region":{"detail":"Global routing across hundreds of hosted endpoints; enterprise in-region routing exists but is not the default.","source":"https://openrouter.ai/docs/guides/privacy/provider-logging"},"routing":{"detail":"Aggregates many upstream providers worldwide; data policies vary per endpoint.","source":"https://openrouter.ai/docs/guides/privacy/provider-logging"}}};

